// ELEMENTS:
// 1. Navy liso com o filete vermelho no topo
// 2. Anel de marcas finas (uma por unidade, até 60) que se acendem a branco enquanto o número conta
// 3. Número grande (anim.text, ex. "60 dias") a contar no centro, label em cima e sub em baixo
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.08, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const ContadorAnel: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const label = String(p.label ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const text = String(anim.text ?? "").trim();
  const m = text.match(/\d+/);
  const target = m ? parseInt(m[0], 10) : 0;
  const unit = m ? text.slice((m.index ?? 0) + m[0].length).trim() : text;
  const ticks = Math.max(12, Math.min(60, target || 60));

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` };
  };
  const count = interpolate(f, [Math.round(0.4 * fps), Math.round(2.4 * fps)], [0, 1], { ...clamp, easing: Easing.out(Easing.cubic) });
  const R = 330 * u;
  const size = R * 2 + 80 * u;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 50 * u }}>
        {label ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 32 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, ...rise(0.1) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {label}
          </div>
        ) : null}
        <div style={{ position: "relative", width: size, height: size }}>
          <svg width={size} height={size} viewBox={`${-size / 2} ${-size / 2} ${size} ${size}`} style={{ position: "absolute", inset: 0 }}>
            {Array.from({ length: ticks }, (_, i) => {
              const a = (i / ticks) * Math.PI * 2 - Math.PI / 2;
              const lit = i < count * ticks;
              const head = lit && i >= count * ticks - 1 && count < 1;
              const len = (i % 5 === 0 ? 34 : 20) * u;
              return (
                <line key={i} x1={Math.cos(a) * R} y1={Math.sin(a) * R} x2={Math.cos(a) * (R - len)} y2={Math.sin(a) * (R - len)}
                  stroke={head ? RED : lit ? WHITE : "rgba(255,255,255,0.18)"} strokeWidth={(i % 5 === 0 ? 4 : 2.5) * u} strokeLinecap="round" />
              );
            })}
          </svg>
          <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", ...rise(0.2) }}>
            <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 250 * u, lineHeight: 1, color: WHITE, fontVariantNumeric: "lining-nums tabular-nums" }}>{Math.round(target * count)}</div>
            {unit ? <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 70 * u, color: WHITE, marginTop: 6 * u }}>{unit}</div> : null}
          </AbsoluteFill>
        </div>
        {sub ? (
          <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 56 * u, lineHeight: 1.15, color: WHITE, textAlign: "center", maxWidth: 900 * u, ...rise(2.2) }}>{sub}</div>
        ) : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default ContadorAnel;
